type SerializedValue =
  | [ValueOf<typeof PROP_TYPE>, any]
  | [ValueOf<typeof PROP_TYPE>];

// serializeArray and serializeObject recurse through convertToSerializedForm, which is
// defined after them, so they receive it as a parameter instead of referencing it.
type ConvertToSerializedForm = (
  value: any,
  metadata: AstroComponentMetadata | Record<string, any>,
  parents: WeakSet<any>
) => SerializedValue;

const serializeArray = (
  convert: ConvertToSerializedForm,
  value: any[],
  metadata: AstroComponentMetadata | Record<string, any> = {},
  parents = new WeakSet<any>()
): any[] => {
  if (parents.has(value)) {
    throw new Error(`Cyclic reference detected while serializing props for <${metadata.displayName} client:${metadata.hydrate}>!

